import glob,re
for f in glob.glob('*.txt'):
 s=open(f).read(); p=0; lines=s.splitlines(); hits=[]
 for i,l in enumerate(lines):
  if re.match(r'--- page (\\d+) ---',l):p=int(re.search(r'\\d+',l).group())
  if re.search(r'exclusiv|shall not|will not|agrees not|competitor|competing|only from',l,re.I):
   if re.search(r'exclusiv',l,re.I) and re.search(r'non.exclus|exclusive (remed|juris|property|owner)|exclusively (by|under)|sole and exclusive (rem|own)',l,re.I):continue
   hits.append((i,p))
 print('\\nFILE',f)
 for i,p in hits:
  print('PAGE',p, '\\n'+'\\n'.join(lines[max(0,i-1):i+5]))
PY"

